def titulo():
    return t("Resources, the environment, and sustainability", "Recursos, medio ambiente y sostenibilidad")


def svg_cadena():
    pasos = [(t("1 · Distribution", "1 · Distribución"), t("The resource is", "El recurso está"), t("in a few places", "en pocos sitios")),
             (t("2 · Trade", "2 · Comercio"), t("Those who need it", "Quien lo necesita"), t("buy it", "lo compra")),
             (t("3 · Dependence", "3 · Dependencia"), t("And with it, the power", "Y con ella, capacidad"), t("to apply pressure", "de presión"))]
    aria = t("A three-step chain. A resource is concentrated in a few places. That forces trade between those who have it and those who need it. And from that trade comes a dependence that can become political pressure. Each arrow means “and that is why.”",
             "Cadena de tres pasos. Un recurso está concentrado en pocos lugares. Eso obliga a comerciar entre quien lo tiene y quien lo necesita. Y de ese comercio nace una dependencia que puede convertirse en presión política. Cada flecha significa «por eso».")
    s = [f'<svg class="diagrama" style="max-width:720px" viewBox="0 0 720 170" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">',
         '<defs><marker id="fl73" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#2e6b30"/></marker></defs>']
    for i, (a, b, c) in enumerate(pasos):
        x = 20 + i * 240
        s.append(f'<rect x="{x}" y="20" width="200" height="100" rx="12" fill="#eef5ec" stroke="#2e6b30" stroke-width="2"/>'
                 f'<text x="{x + 100}" y="52" text-anchor="middle" {F} font-size="16" font-weight="700" fill="#2e6b30">{a}</text>'
                 f'<text x="{x + 100}" y="80" text-anchor="middle" {F} font-size="14" fill="#1a2330">{b}</text>'
                 f'<text x="{x + 100}" y="100" text-anchor="middle" {F} font-size="14" fill="#1a2330">{c}</text>')
        if i < 2:
            s.append(f'<line x1="{x + 204}" y1="70" x2="{x + 236}" y2="70" stroke="#2e6b30" stroke-width="3" marker-end="url(#fl73)"/>')
    s.append(f'<text x="360" y="152" text-anchor="middle" {F} font-size="13" fill="#3d4753">{t("Each arrow means “and that is why”: the step before explains the next one.", "Cada flecha significa «por eso»: el paso anterior explica el siguiente.")}</text>')
    s.append("</svg>")
    return "".join(s)


def doc_mayoria():
    ficha = [(t("Case", "Caso"), t("<cite>Massachusetts v. Environmental Protection Agency</cite>, 549 U.S. 497", "<cite>Massachusetts contra la Agencia de Protección Ambiental</cite>, 549 U.S. 497")),
             (t("Date", "Fecha"), t("April 2, 2007 · decided 5 to 4", "2 de abril de 2007 · decidido 5 contra 4")),
             (t("Author", "Autor"), t("Justice John Paul Stevens, for the majority", "El juez John Paul Stevens, por la mayoría")),
             (t("Kind of source", "Tipo de fuente"), t("Primary · court opinion. Excerpts.", "Primaria · sentencia. Fragmentos."))]
    partes = [("", ["A well-documented rise in global temperatures has coincided with a significant increase in the concentration of carbon dioxide in the atmosphere. Respected scientists believe the two trends are related. […]",
                    "Because greenhouse gases fit well within the Clean Air Act’s capacious definition of “air pollutant,” we hold that EPA has the statutory authority to regulate the emission of such gases from new motor vehicles. […]",
                    "We hold only that EPA must ground its reasons for action or inaction in the statute."],
               ["Un aumento bien documentado de las temperaturas globales ha coincidido con un incremento significativo de la concentración de dióxido de carbono en la atmósfera. Científicos respetados creen que las dos tendencias están relacionadas. […]",
                "Como los gases de efecto invernadero encajan sin dificultad en la amplia definición de «contaminante atmosférico» de la Ley de Aire Limpio, sostenemos que la EPA tiene autoridad legal para regular la emisión de esos gases por los vehículos nuevos. […]",
                "Sostenemos únicamente que la EPA debe fundar en la ley sus razones para actuar o para no actuar."])]
    return documento(t("Document A · The majority", "Documento A · La mayoría"), ficha, partes)


def doc_disidencia():
    ficha = [(t("Case", "Caso"), t("The same case and the same day", "El mismo caso y el mismo día")),
             (t("Author", "Autor"), t("Chief Justice John Roberts, dissenting, for four justices", "El presidente del Tribunal, John Roberts, en disidencia, por cuatro jueces")),
             (t("Kind of source", "Tipo de fuente"), t("Primary · dissenting opinion. Excerpts.", "Primaria · opinión disidente. Fragmentos."))]
    partes = [("", ["Global warming may be a “crisis,” even “the most pressing environmental problem of our time.” […] It is not a problem, however, that has escaped the attention of policymakers in the Executive and Legislative Branches of our Government, who continue to consider regulatory, legislative, and treaty-based means of addressing global climate change.",
                    "Apparently dissatisfied with the pace of progress on this issue in the elected branches, petitioners have come to the courts claiming broad-ranging injury, and attempting to tie that injury to the Government’s alleged failure to comply with a rather narrow statutory provision. I would reject these challenges as nonjusticiable. Such a conclusion involves no judgment on whether global warming exists, what causes it, or the extent of the problem."],
               ["El calentamiento global puede ser una «crisis», incluso «el problema ambiental más apremiante de nuestro tiempo». […] No es, sin embargo, un problema que haya escapado a la atención de los responsables políticos de los poderes ejecutivo y legislativo de nuestro gobierno, que siguen estudiando vías reglamentarias, legislativas y de tratados para abordar el cambio climático global.",
                "Aparentemente insatisfechos con el ritmo de avance de este asunto en los poderes electos, los demandantes han acudido a los tribunales alegando un daño de alcance muy amplio, e intentando vincularlo al supuesto incumplimiento por el gobierno de una disposición legal bastante estrecha. Yo rechazaría estas impugnaciones por no ser justiciables. Tal conclusión no implica juicio alguno sobre si el calentamiento global existe, sobre qué lo causa o sobre la magnitud del problema."])]
    return documento(t("Document B · The dissent", "Documento B · La disidencia"), ficha, partes)


