def casos_quien():
    G = [t("The majority (A)", "La mayoría (A)"), t("The dissent (B)", "La disidencia (B)"), t("Both", "Las dos"), t("Neither", "Ninguna")]
    PI = [t("Is it about the EPA’s authority under the law?", "¿Trata de la autoridad de la EPA según la ley?"), t("Is it about who should decide, or who may sue?", "¿Trata de quién debe decidir, o de quién puede demandar?"), t("Do both texts say or accept this?", "¿Lo dicen o aceptan los dos textos?"), t("Does either text actually say this, or is it an assumption?", "¿Lo dice de verdad alguno de los textos, o es una suposición?")]
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("Where does each statement come from?", "¿De dónde sale cada afirmación?"), "grupos": G, "etiqueta": t("It comes from…", "Sale de…"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("Greenhouse gases fit the legal definition of an air pollutant.", "Los gases de efecto invernadero encajan en la definición legal de contaminante atmosférico."), 0), (t("This issue belongs to Congress and the President, not to the courts.", "Este asunto corresponde al Congreso y al presidente, no a los tribunales."), 1),
                                      (t("Global warming is a serious matter.", "El calentamiento global es un asunto serio."), 2), (t("The Court orders the EPA to regulate greenhouse gases.", "El Tribunal ordena a la EPA regular los gases de efecto invernadero."), 3)]),
        caso(t("Set 2", "Serie 2"), [(t("The harm Massachusetts claims is too broad, and its link to the EPA’s refusal too speculative.", "El daño que alega Massachusetts es demasiado general, y su relación con la negativa de la EPA, demasiado especulativa."), 1), (t("Climate science is wrong.", "La ciencia del clima es incorrecta."), 3),
                                      (t("The decision on this matter must rest on what the law says.", "La decisión sobre este asunto debe fundarse en lo que dice la ley."), 2), (t("The author of the dissent denies that climate change exists.", "Quien firmó la disidencia niega que exista el cambio climático."), 3)]),
    ]


def banco_recursos():
    D = [(t("A country has huge oil reserves. What can you conclude?", "Un país tiene enormes reservas de petróleo. ¿Qué se puede concluir?"), [t("That it has a valuable resource; its wealth depends on other questions", "Que tiene un recurso valioso; su riqueza depende de otras preguntas"), t("That it is rich", "Que es rico"), t("That it does not trade", "Que no comercia")], t("Who owns it and where the profit goes decide.", "Deciden quién es dueño y adónde va el beneficio.")),
         (t("A country mines rare earths but sends them abroad to be processed. Its main dependence is on…", "Un país extrae tierras raras, pero las envía al extranjero para procesarlas. Su dependencia principal está en…"), [t("whoever controls processing", "quien controla el procesamiento"), t("its own mines", "sus propias minas"), t("the buyers of finished phones", "los compradores de teléfonos terminados")], t("The bottleneck is processing.", "El cuello de botella es el procesamiento.")),
         (t("A map shades countries by total emissions. A student says “people in the darkest country pollute the most.” What is wrong?", "Un mapa colorea los países según sus emisiones totales. Un estudiante dice «la gente del país más oscuro es la que más contamina». ¿Qué falla?"), [t("The map shows totals, not per person", "El mapa muestra totales, no por habitante"), t("Nothing", "Nada"), t("The map has no title", "El mapa no tiene título")], t("Check the units first.", "Compruebe primero las unidades.")),
         (t("A straight-line border cuts through a region with one language. What may result?", "Una frontera en línea recta atraviesa una región con una sola lengua. ¿Qué puede resultar?"), [t("Tension, mixing, or both, because the political and cultural borders do not match", "Tensión, mezcla o las dos cosas, porque las fronteras política y cultural no coinciden"), t("Nothing at all", "Nada"), t("The language disappears at once", "La lengua desaparece de inmediato")], t("Neither dooms anything; it explains tensions.", "Ninguna condena a nada; explica tensiones.")),
         (t("In 2007, what did the Supreme Court majority hold?", "En 2007, ¿qué sostuvo la mayoría del Tribunal Supremo?"), [t("The EPA had authority and must ground its decision in the law", "La EPA tenía autoridad y debía fundar su decisión en la ley"), t("The EPA must regulate at once", "La EPA debía regular de inmediato"), t("The EPA had no authority", "La EPA no tenía autoridad")], t("“We hold only…”", "«Sostenemos únicamente…»")),
         (t("Summing up the 2007 case as “some believe in climate change and some don’t” is…", "Resumir el caso de 2007 como «unos creen en el cambio climático y otros no» es…"), [t("wrong: the disagreement is about who decides", "un error: el desacuerdo es sobre quién decide"), t("accurate", "exacto"), t("what the dissent says", "lo que dice la disidencia")], t("The dissent expressly does not judge that.", "La disidencia dice expresamente que no juzga eso."))]
    return [{"enun": "<strong>" + s + "</strong>", "ops": ops, "ok": 0, "exp": e} for s, ops, e in D]


def tx():
    return {"pc": t("Country {n} emits {e} million tons of CO₂ a year and has {p} million people. How many tons does it emit per person?", "El país {n} emite {e} millones de toneladas de CO₂ al año y tiene {p} millones de habitantes. ¿Cuántas toneladas emite por persona?"),
            "pide": t("Write the number of tons per person.", "Escriba el número de toneladas por persona."),
            "alReves": t("You divided population by emissions. Divide emissions by population.", "Dividió la población entre las emisiones. Divida las emisiones entre la población."),
            "pcP": t("Per person = total ÷ population.", "Por habitante = total ÷ población."),
            "ton": t(" tons per person.", " toneladas por persona.")}


JS = r"""
function gPC(){
  var pp = elige([2, 4, 5, 8, 10, 20, 25, 40, 50, 80, 120, 200, 300]), r = elige([1.5, 2, 2.5, 3, 4, 5, 6, 7.5, 8, 10, 12, 15, 16]);
  var e = Math.round(pp * r * 10) / 10;
  var enun = "<p>" + TXS.pc.replace("{n}", elige(["A", "B", "C", "D", "E"])).replace("{e}", com(e)).replace("{p}", com(pp)) + "</p><p>" + TXS.pide + "</p>";
  return {enun: enun, resp: leeNumero(String(r)), explica: com(e) + " ÷ " + com(pp) + " = " + r + TXS.ton,
    pista: function(x){ if (igual(x, leeNumero(String(Math.round(pp / e * 1000) / 1000)))) return TXS.alReves; return TXS.pcP; }};
}
"""


